function read(path) { return readFileSync(path, 'utf8'); }
function write(path, content) { mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, content.endsWith('\n') ? content : `${content}\n`, 'utf8'); }
function replaceOnce(path, search, replacement) {
  const source = read(path);
  const index = source.indexOf(search);
  if (index < 0) throw new Error(`Expected text was not found in ${path}: ${search.slice(0, 120)}`);
  if (source.indexOf(search, index + search.length) >= 0) throw new Error(`Expected one match but found multiple in ${path}: ${search.slice(0, 120)}`);
  write(path, source.slice(0, index) + replacement + source.slice(index + search.length));
}
function replaceRegexOnce(path, regex, replacement) {
  const source = read(path);
  const matches = [...source.matchAll(new RegExp(regex.source, regex.flags.includes('g') ? regex.flags : `${regex.flags}g`))];
  if (matches.length !== 1) throw new Error(`Expected one regex match in ${path}, found ${matches.length} for ${regex}`);
  write(path, source.replace(regex, replacement));
}
function replaceScopedSegment(path, scopeMarker, startMarker, endMarker, replacement) {
  const source = read(path);
  const scope = source.indexOf(scopeMarker);
  if (scope < 0) throw new Error(`Scope marker not found in ${path}: ${scopeMarker}`);
  const start = source.indexOf(startMarker, scope);
  if (start < 0) throw new Error(`Start marker not found in ${path}: ${startMarker}`);
  const end = source.indexOf(endMarker, start + startMarker.length);
  if (end < 0) throw new Error(`End marker not found in ${path}: ${endMarker}`);
  write(path, source.slice(0, start) + replacement + source.slice(end));
}

